snippet_css:
:root{
  --bg: #FFFFFF;
  --fg: #161616;
  --muted: #565656;
  --surface: #F4F4F4;
  --border: #DCDCDC;
  --accent: #0F62FE;
  --accent-fg: #FFFFFF;
  --radius: 8px;
  --radius-sm: 8px;
  --shadow: none;
  --btn-shadow: none;
  --art-bg: #F4F4F4;
  --media-bg: #F4F4F4;
  --cta-bg: #F4F4F4;
  --input-bg: #FFFFFF;
  --ok: #0F8A3C;
  --warn: #DA1E28;
  --font-display: 'IBM Plex Sans','Archivo Black',sans-serif;
  --font-body: 'IBM Plex Sans','Noto Sans TC',sans-serif;
  --focus-ring: var(--accent);
}

snippet_tailwind:
// tailwind.config.js → theme.extend
{
  "colors": {
    "bg": "#FFFFFF",
    "fg": "#161616",
    "muted": "#565656",
    "surface": "#F4F4F4",
    "border": "#DCDCDC",
    "accent": "#0F62FE",
    "accent-fg": "#FFFFFF",
    "ok": "#0F8A3C",
    "warn": "#DA1E28",
    "focus-ring": "var(--accent)"
  },
  "borderRadius": {
    "DEFAULT": "8px",
    "lg": "8px"
  },
  "fontFamily": {
    "display": [
      "'IBM Plex Sans','Archivo Black',sans-serif"
    ],
    "body": [
      "'IBM Plex Sans','Noto Sans TC',sans-serif"
    ]
  }
}
